import { apiRaw } from "@/lib/server/api";
import { authorize } from "@/lib/server/auth";
import { jsonError } from "@/lib/server/request";

/* Streams the CSV export generated by Laravel. */
export async function GET() {
    const session = await authorize();
    if (!session) return jsonError("Not signed in", 401);

    const res = await apiRaw("/admin/leads/export", session.token);
    if (!res.ok || !res.body) return jsonError("Export failed.", res.status || 500);

    return new Response(res.body, {
        headers: {
            "Content-Type": res.headers.get("content-type") ?? "text/csv; charset=utf-8",
            "Content-Disposition": res.headers.get("content-disposition") ?? 'attachment; filename="esupport-enquiries.csv"',
        },
    });
}
